import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

/// UI code that must not contain user-facing string literals
/// (vv-flutter-architecture → UI conventions). Paths relative to `app/`.
const _scanned = ['lib/core/routing', 'lib/core/widgets', 'lib/app.dart'];
const _presentationRoot = 'lib/features';

/// Files exempt from the scan, with the reason.
const _allowlist = {
  // Dev-flavor-only SEC-09 diagnostics screen, never shown to users.
  'lib/features/recording/presentation/call_guard_debug_screen.dart',
  // Generated by go_router_builder.
  'lib/core/routing/app_routes.g.dart',
};

/// Widgets/arguments whose string argument is shown to (or read to) the user.
final _patterns = <RegExp>[
  RegExp(r'''\b(?:Text|SelectableText|Tooltip)\(\s*(['"])'''),
  RegExp(
    r'''\b(?:label|tooltip|semanticLabel|semanticsLabel|hintText|labelText|'''
    '''helperText|errorText|message|title|subtitle|content|actionLabel|'''
    r'''applicationName|applicationLegalese)\s*:\s*(?:const\s+)?(['"])''',
  ),
];

/// A literal is user-facing if, after removing interpolations, escapes and
/// symbols, it still contains a letter.
bool _hasWords(String literal) {
  final stripped = literal
      .replaceAll(RegExp(r'\$\{[^}]*\}'), '')
      .replaceAll(RegExp(r'\$[A-Za-z_]\w*'), '')
      .replaceAll(RegExp(r'\\.'), '');
  return RegExp('[A-Za-z]').hasMatch(stripped);
}

/// Returns `path:line: literal` for every hard-coded user-facing string.
List<String> scan(String path, String source) {
  final hits = <String>[];
  final lines = const LineSplitter().convert(source);
  for (final (i, line) in lines.indexed) {
    final code = line.trimLeft();
    if (code.startsWith('//') || code.startsWith('import ')) continue;
    for (final p in _patterns) {
      for (final m in p.allMatches(line)) {
        final quote = m.group(1)!;
        final start = m.end;
        final end = line.indexOf(quote, start);
        final literal = end < 0
            ? line.substring(start)
            : line.substring(start, end);
        if (_hasWords(literal)) hits.add('$path:${i + 1}: $literal');
      }
    }
  }
  return hits;
}

Iterable<File> _uiFiles() sync* {
  for (final entry in _scanned) {
    final type = FileSystemEntity.typeSync(entry);
    if (type == FileSystemEntityType.file) {
      yield File(entry);
    } else if (type == FileSystemEntityType.directory) {
      yield* Directory(entry).listSync(recursive: true).whereType<File>();
    }
  }
  yield* Directory(_presentationRoot)
      .listSync(recursive: true)
      .whereType<File>()
      .where((f) => f.path.contains('/presentation/'));
}

void main() {
  test('[APP-06/AC2] no hard-coded user-facing strings in UI code '
      '(all text comes from lib/core/l10n/arb/app_en.arb)', () {
    final files = [
      for (final f in _uiFiles())
        if (f.path.endsWith('.dart') &&
            !f.path.endsWith('.g.dart') &&
            !_allowlist.contains(f.path))
          f,
    ];
    expect(files.length, greaterThan(10), reason: 'scan found the UI files');
    final hits = [for (final f in files) ...scan(f.path, f.readAsStringSync())];
    expect(hits, isEmpty, reason: hits.join('\n'));
  });

  test('[APP-06/AC2] the scanner catches hard-coded strings', () {
    expect(scan('x.dart', "  child: Text('Hello'),"), hasLength(1));
    expect(scan('x.dart', '  title: const Text("Save"),'), hasLength(1));
    expect(scan('x.dart', "  tooltip: 'Remove folder',"), hasLength(1));
    expect(scan('x.dart', "  semanticsLabel: 'Loading',"), hasLength(1));
    expect(scan('x.dart', "  message: 'Could not load.',"), hasLength(1));
    // Not user-facing: interpolation/symbols only, keys, comments.
    expect(scan('x.dart', r"  child: Text('${i + 1}'),"), isEmpty);
    expect(scan('x.dart', "  child: Text(' '),"), isEmpty);
    expect(scan('x.dart', "  key: ValueKey('setting-x'),"), isEmpty);
    expect(scan('x.dart', "  // Text('Hello')"), isEmpty);
    expect(scan('x.dart', '  child: Text(context.l10n.commonSave),'), isEmpty);
  });

  test('every ARB key is used and every used key exists', () {
    final arb = jsonDecode(
      File('lib/core/l10n/arb/app_en.arb').readAsStringSync(),
    ) as Map<String, Object?>;
    final keys = arb.keys.where((k) => !k.startsWith('@')).toSet();
    final source = StringBuffer();
    for (final f in Directory(
      'lib',
    ).listSync(recursive: true).whereType<File>()) {
      if (f.path.endsWith('.dart') && !f.path.contains('/l10n/gen/')) {
        source.write(f.readAsStringSync());
      }
    }
    final code = source.toString();
    final unused = [
      for (final k in keys)
        if (!RegExp('\\.$k\\b').hasMatch(code)) k,
    ];
    expect(unused, isEmpty, reason: 'unused ARB keys: $unused');
  });
}
